import math

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def num_divisors(n):
    if n == 1:
        return 1
    factors = get_prime_factorization(n)
    num = 1
    for exponent in factors.values():
        num *= (exponent + 1)
    return num

results = []
for k in range(1, 16):
    n = 2 * (k**3)
    d_n = num_divisors(n)
    target = 2 * k
    match = d_n == target
    results.append((k, n, d_n, target, match))

print("k | 2k^3 | d(2k^3) | 2k | Match")
print("-" * 30)
for k, n, d_n, target, match in results:
    print(f"{k} | {n} | {d_n} | {target} | {match}")

import math

def count_divisors(n):
    if n <= 0:
        return 0
    count = 1
    d = 2
    temp = n
    while d * d <= temp:
        exponent = 0
        while temp % d == 0:
            exponent += 1
            temp //= d
        if exponent > 0:
            count *= (exponent + 1)
        d += 1
    if temp > 1:
        count *= 2
    return count

def check_solution(k):
    target = 2 * k
    num = 2 * (k**3)
    d_val = count_divisors(num)
    return d_val == target, d_val, target

# Test candidates found by W3 and W4: k=1, 4, 10, 49
candidates = [1, 4, 10, 49]
results = {}

for k in candidates:
    is_solution, d_val, target = check_solution(k)
    results[k] = (is_solution, d_val, target)

print("Verification Results for Candidates (d(2k^3) vs 2k):")
for k, (is_solution, d_val, target) in results.items():
    status = "Solution" if is_solution else "NOT Solution"
    print(f"k={k}: d(2k^3)={d_val} vs 2k={target}. Status: {status}")
